"""Policy/ranking checks and independent spatial evaluator sanity checks."""
import json
from pathlib import Path
import numpy as np
import pandas as pd
import pytest
from src.pipeline import decide
from src.common.context import RunContext
from src.t07_review import build_queue
from src.metrics.tracks import eval_t07

def test_low_confidence_has_priority():
    # Use candidates generated by the real integration-test fixture run.
    from src.t07_detector import detect_and_score
    from src.t07_contract import load_images
    ctx=RunContext('t07',Path('fixtures/t07_redaction'),Path('.'),{},42,np.random.default_rng(42))
    candidates=detect_and_score(ctx,load_images(ctx.input_dir))
    np.testing.assert_allclose(candidates.score,1-candidates.confidence,atol=1.1e-6)
    queue=build_queue(candidates,budget=15)
    expected=candidates.sort_values(['score','region_id'],ascending=[False,True],kind='stable').head(15)
    assert queue.item_id.tolist()==expected.region_id.tolist()
    assert queue.score.is_monotonic_decreasing

@pytest.mark.parametrize('review,n,expected',[
    ({'pending':15},1,('REWORK','REVIEW_PENDING')),
    ({'pending':0,'escalated':['r1']},1,('REWORK','REVIEW_ESCALATED')),
    ({'pending':0,'stale':['old']},1,('REWORK','STALE_REVIEW')),
    ({'pending':0,'escalated':[],'stale':[]},1,('GO','REVIEW_COMPLETE')),
    ({'pending':0},0,('HOLD','NO_REDACTIONS')),
])
def test_operational_decisions(tmp_path,review,n,expected):
    ctx=RunContext('t07',tmp_path,tmp_path,{'owner':'QA fixture'},42,np.random.default_rng(42))
    ctx.stats['review']=review
    decision=decide(ctx,pd.DataFrame({'image_id':['sample']*n}))
    assert (decision.status,decision.reason_code)==expected
    assert decision.owner=='QA fixture'

@pytest.mark.parametrize('full_image',[False,True],ids=['exact_mask','blur_all_guardrail'])
def test_spatial_metric_not_count_proxy(tmp_path,full_image):
    root=tmp_path/'synthetic_eval'; root.mkdir()
    pd.DataFrame([dict(image_id='a',width=20,height=10,split='eval')]).to_csv(root/'images.csv',index=False)
    box=dict(image_id='a',x=1,y=1,w=2,h=2)
    pd.DataFrame([dict(box,region_id='g1',type='face',condition='synthetic_unit',split='eval',must_redact=1)]).to_csv(root/'regions.csv',index=False)
    pred=dict(image_id='a',x=0,y=0,w=20,h=10) if full_image else box
    pd.DataFrame([pred]).to_csv(root/'pred.csv',index=False)
    result=eval_t07(root/'regions.csv',root/'pred.csv',{'split':'eval','min_coverage':0.9,'max_over_redaction':0.3})
    metrics={m.name:m.value for m in result.metrics}
    assert metrics['PII Miss Rate']==0
    assert metrics['Over-redaction rate']==(0.98 if full_image else 0)
    guard=next(m for m in result.metrics if m.name.startswith('Guardrail:'))
    assert guard.value==(0 if full_image else 1)
